def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((oid, opp))

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    eric_prev = None
    highest_prev = 0.0
    urgent_opp_count = 0

    for oid, opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid_val = float(bid)
            prev_bids.append(bid_val)
            if bid_val > highest_prev:
                highest_prev = bid_val
            if oid == 'Eric':
                eric_prev = bid_val

    if eric_prev is None:
        eric_prev = highest_prev

    scarcity = (float(supply) <= 18.0)
    abundance = (float(supply) >= 22.0)
    my_urgent = (hp <= 2 or no_water_days >= 1)
    very_urgent = (hp <= 1 or no_water_days >= 2)

    target = DAILY_SALARY * 0.45

    if very_urgent:
        target = max(target, DAILY_SALARY * 0.96)
    elif my_urgent:
        if scarcity:
            target = max(target, DAILY_SALARY * 0.9)
        else:
            target = max(target, DAILY_SALARY * 0.78)
    else:
        if scarcity:
            if eric_prev > 0:
                target = max(target, min(DAILY_SALARY * 0.95, eric_prev + 2.0))
            else:
                target = max(target, DAILY_SALARY * 0.72)
        elif abundance:
            if urgent_opp_count == 0 and hp >= 4:
                target = max(target, DAILY_SALARY * 0.28)
            else:
                target = max(target, DAILY_SALARY * 0.4)
        else:
            if eric_prev >= DAILY_SALARY * 0.85:
                target = max(target, DAILY_SALARY * 0.52 if hp >= 4 else DAILY_SALARY * 0.82)
            elif eric_prev > 0:
                target = max(target, min(DAILY_SALARY * 0.82, eric_prev + 1.5))
            else:
                target = max(target, DAILY_SALARY * 0.55)

    days_left = max(0, 10 - int(day) + 1)
    reserve_floor = 0.0
    if days_left > 1 and hp >= 3 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 0.25 * (days_left - 1)

    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor
    if my_urgent:
        affordable = budget

    bid = min(target, affordable)
    if scarcity and not my_urgent and eric_prev > 0:
        bid = min(max(bid, eric_prev + 1.0), budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = float(day_context['supply'])  # convert to float explicitly
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    # get yesterday's max bid among alive opponents
    yesterday_max_bid = 0.0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid_val = float(prev['bid'])
            if bid_val > yesterday_max_bid:
                yesterday_max_bid = bid_val

    # base bid: beat yesterday's max by a small margin, else moderate
    if yesterday_max_bid > 0:
        base_bid = yesterday_max_bid + 5.0
    else:
        base_bid = DAILY_SALARY * 0.55

    # adjust based on HP
    if hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)
    elif hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.65)
    elif hp >= 8:
        base_bid = min(base_bid, DAILY_SALARY * 0.45)

    # adjust based on supply
    if supply < 18:
        base_bid *= 1.2
    elif supply > 22:
        base_bid *= 0.8

    # ensure within bounds
    min_bid = DAILY_SALARY * 0.2
    max_bid = min(budget, DAILY_SALARY * 0.95)
    bid = max(min_bid, min(max_bid, base_bid))

    # round to two decimals for cleanliness
    bid = round(bid, 2)
    return bid
